#!/usr/bin/env python3
"""Generate the parameter tables in docs/RULESETS.md from the rule-set files.

Every released Big Bad Bots rule set has a file under
``packages/python/src/chipzen/rulesets/bigbadbots/`` (the SDK's bundled copy,
read by ``chipzen.bigbadbots_rules.published_rule_set()``). Its changelog entry
in ``docs/RULESETS.md`` section 7 carries the same numbers as a table, between
two marker lines::

    <!-- ruleset-table:bigbadbots-1.2 begin (generated by ...; do not edit) -->
    ...
    <!-- ruleset-table:bigbadbots-1.2 end -->

The table is rendered from the file, so the published numbers cannot drift
from the bundled ones (chipzen-ai/chipzen-sdk#138).

    python scripts/rulesets_tables.py           # rewrite the tables in place
    python scripts/rulesets_tables.py --check   # CI: fail if any table is stale

``--check`` also fails when a released file has no table in the doc, when the
doc has a table for a rule set with no file, and when the sha256 the entry
states differs from the file's.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
DOC = REPO / "docs" / "RULESETS.md"
RULESET_DIR = REPO / "packages" / "python" / "src" / "chipzen" / "rulesets" / "bigbadbots"
RULESET_DIR_REL = RULESET_DIR.relative_to(REPO).as_posix()

# The sections of the full table, in the order RULESETS.md section 4 lists them.
SECTION_ORDER = [
    "attributes",
    "slot_types",
    "gearup",
    "bodies",
    "parts",
    "moves",
    "specials",
    "arena",
    "rounds",
    "fighter",
    "combat",
    "special_effects",
    "forfeit",
    "deadline",
]

BLOCK_RE = re.compile(
    r"<!-- ruleset-table:(?P<id>[a-z0-9.-]+) begin[^>]*-->\n"
    r"(?P<body>.*?)"
    r"<!-- ruleset-table:(?P=id) end -->",
    re.DOTALL,
)
HEADING_RE = re.compile(r"^### `(?P<id>[a-z0-9.-]+)`", re.MULTILINE)
SHA_RE = re.compile(r"\*\*sha256\*\*[^`]*`(?P<sha>[0-9a-f]{64})`")


def _value(v: object) -> str:
    return "`" + json.dumps(v, ensure_ascii=True) + "`"


def _rows(prefix: str, value: object) -> list[tuple[str, str]]:
    """Flatten nested objects into dotted keys; lists and scalars are leaves."""
    if isinstance(value, dict):
        rows: list[tuple[str, str]] = []
        for key, sub in value.items():
            rows.extend(_rows(f"{prefix}.{key}" if prefix else key, sub))
        return rows
    return [(prefix, _value(value))]


def render(data: dict) -> str:
    """The generated block body for one rule-set file."""
    rule_set = data["rule_set"]
    unknown = sorted(set(rule_set) - set(SECTION_ORDER))
    if unknown:
        raise SystemExit(
            f"{data['rule_set_id']}: unknown section(s) {unknown}; add them to SECTION_ORDER"
        )
    present = [s for s in SECTION_ORDER if s in rule_set]
    missing = [s for s in SECTION_ORDER if s not in rule_set]

    lines = [
        f"Parameter table of `{data['rule_set_id']}`, generated from "
        f"[`{data['rule_set_id']}.json`](../{RULESET_DIR_REL}/{data['rule_set_id']}.json) "
        f"(engine `{data['engine']}`, frozen on {data['frozen_on']}):",
        "",
        "| Section | Parameter | Value |",
        "|---|---|---|",
    ]
    for section in present:
        for key, val in _rows("", rule_set[section]):
            lines.append(f"| `{section}` | `{key}` | {val} |")
    if missing:
        lines.append("")
        lines.append(
            "Not published yet: "
            + ", ".join(f"`{s}`" for s in missing)
            + ". These sections are added to the file, and so to this table,"
            " when their numbers are published."
        )
    return "\n".join(lines) + "\n"


def load_files() -> dict[str, dict]:
    files = {}
    for path in sorted(RULESET_DIR.glob("*.json")):
        data = json.loads(path.read_text(encoding="utf-8"))
        rid = data["rule_set_id"]
        if path.stem != rid:
            raise SystemExit(f"{path.name}: rule_set_id is {rid!r}, expected {path.stem!r}")
        files[rid] = data
    return files


def entry_text(doc: str, rid: str) -> str | None:
    """The text of a changelog entry, from its heading to the next heading."""
    headings = list(HEADING_RE.finditer(doc))
    for i, m in enumerate(headings):
        if m.group("id") == rid:
            end = headings[i + 1].start() if i + 1 < len(headings) else len(doc)
            nxt = doc.find("\n## ", m.end())
            if nxt != -1:
                end = min(end, nxt)
            return doc[m.start() : end]
    return None


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--check", action="store_true", help="fail if any table is stale; write nothing"
    )
    args = parser.parse_args()

    files = load_files()
    doc = DOC.read_text(encoding="utf-8")
    errors: list[str] = []

    blocks = {m.group("id") for m in BLOCK_RE.finditer(doc)}
    for rid in sorted(set(files) - blocks):
        errors.append(f"{rid}: released file has no generated table in {DOC.name} (add markers)")
    for rid in sorted(blocks - set(files)):
        errors.append(f"{rid}: {DOC.name} has a table but there is no {rid}.json")

    for rid, data in files.items():
        entry = entry_text(doc, rid)
        if entry is None:
            errors.append(f"{rid}: no changelog entry (### `{rid}`) in {DOC.name}")
            continue
        sha = SHA_RE.search(entry)
        if sha is None or sha.group("sha") != data["sha256"]:
            errors.append(f"{rid}: the entry's sha256 does not match the file's ({data['sha256']})")

    def replace(m: re.Match[str]) -> str:
        rid = m.group("id")
        if rid not in files:
            return m.group(0)
        body = render(files[rid])
        if args.check and m.group("body") != body:
            errors.append(f"{rid}: table is stale; run python scripts/rulesets_tables.py")
        begin = m.group(0).split("\n", 1)[0]
        return f"{begin}\n{body}<!-- ruleset-table:{rid} end -->"

    new_doc = BLOCK_RE.sub(replace, doc)

    if errors:
        for e in errors:
            print(f"::error file=docs/RULESETS.md::{e}")
        return 1
    if not args.check and new_doc != doc:
        DOC.write_text(new_doc, encoding="utf-8", newline="\n")
        print(f"updated {DOC.relative_to(REPO).as_posix()}")
    else:
        print(f"{len(files)} rule-set table(s) match their files")
    return 0


if __name__ == "__main__":
    sys.exit(main())
